test('P52-18/29/44/45 candy UI handles HM reselect, per-move decline and one atomic commit',()=>{
 const h=host({setup:{world:{hmMoves:['flamethrower']}},edit:(g,c)=>{g.party[0].hp=1;c.species.Charizard.learnset={51:['Slash','Outrage']};}});const id=h.game.party[0].id,before=clone(h.state.current());const op=h.G.PSInventory.useItem('rarecandy',id);h.ready();assert.equal(h.view()?.view.kind,'menu');assert.equal(h.app.saveBlocked,true);h.choose('0');assert.ok(h.view().text.some(t=>t.includes('cannot be forgotten')));assert.equal(h.state.current().party[0].level,50);h.choose('1');h.ready();h.press('cancel');h.ready();assert.equal(h.view().view.items[0].key,'yes');h.choose('no');h.ready();h.choose('new');h.choose('yes');h.ready();assert.equal(h.state.current().party[0].level,51);assert.equal(h.state.current().party[0].moves[1].id,'slash');assert.equal(E.inventory.aggregateBag(h.state.current().inventory).rarecandy,1);assert.equal(h.state.current().party[0].moves[0].id,before.party[0].moves[0].id);h.press('ok');assert.equal(op.result.status,'committed');assert.equal(h.app.saveBlocked,false);
});
