 h.G.PSInventory.useItem('rarecandy',id);h.ready();const latest=clone(h.state.current());[latest.party[0].moves[0],latest.party[0].moves[1]]=[latest.party[0].moves[1],latest.party[0].moves[0]];h.state.replace(latest);h.choose('0');h.ready();assert.equal(h.view()?.view.kind,'message');assert.deepEqual(h.state.current(),latest);h.press('ok');assert.equal(h.G.PSInventory.current(),null);assert.equal(h.app.saveBlocked,false);assert.equal(h.state.current().party[0].level,before.party[0].level);
