 const h=host(),op=h.G.PSInventory.openShop({stock:['pokeball','potion','box-link']});h.choose('buy');h.choose('pokeball');h.ready();assert.equal(h.view().view.value,1);h.input.repeat.add('right');h.input.trigger.add('ok');h.input.pressed.add('ok');h.tick();assert.equal(h.view()?.view.kind,'quantity');assert.equal(h.view().view.value,11);h.input.pressed.clear();h.tick();h.press('ok');h.ready();assert.equal(h.view().view.items[0].key,'yes');const before=h.state.current().money;h.choose('yes');h.ready();assert.equal(E.inventory.aggregateBag(h.state.current().inventory).pokeball,31);assert.equal(E.inventory.aggregateBag(h.state.current().inventory).premierball,1);assert.ok(h.state.current().money<before);h.press('ok');h.ready();h.press('cancel');h.choose('close');assert.equal(op.result.status,'cancelled');assert.equal(E.inventory.aggregateBag(h.state.current().inventory).pokeball,31);
