const mixedPotions=()=>host({edit:(g,c)=>{g.inventory=E.inventory.replaceItemId(E.inventory.inventoryFromBag({potion:3,pokeball:1500},c.items),'pokeball','potion',c.items);}});
test('FINAL-01/J2-01 cross-pocket bag row reaches menu; zero-stock Use and Toss stay disabled without closing UI',()=>{
 const h=replacedBalls(),before=clone(h.state.current().inventory.pockets),op=h.G.PSInventory.showBag();assert.deepEqual(E.saveSchema.validateGame(h.state.current()),[]);h.pocket(2);h.press('ok');h.ready();assert.equal(op.done,false,'legal visible row must reach its action menu');assert.equal(h.view()?.view.kind,'menu');assert.equal(h.view().view.items.find(i=>i.key==='use').enabled,false);assert.equal(h.view().view.items.find(i=>i.key==='toss').enabled,false);h.press('ok');h.choose('toss');h.ready();assert.equal(h.view().view.kind,'menu');assert.equal(op.done,false);assert.deepEqual(h.state.current().inventory.pockets,before);h.press('cancel');h.ready();assert.equal(h.view().view.kind,'bag');h.press('cancel');assert.equal(op.result.status,'cancelled');
});
test('FINAL-01 cross-pocket script Use returns domain not-ready and filtered selection still restores state',()=>{
 const h=replacedBalls(),before=clone(h.state.current()),op=h.G.PSInventory.useItem('pokeball',h.game.party[0].id);h.ready();assert.equal(op.done,false,'script must reach domain refusal message instead of init failure');assert.equal(h.view()?.view.kind,'message');h.press('ok');assert.equal(op.result.status,'refused');assert.equal(op.result.reason,'not-ready');assert.deepEqual(h.state.current(),before);
 const s=replacedBalls(),old=clone(s.state.current()),selected=s.G.PSInventory.selectItem(i=>i.id==='pokeball');s.ready();assert.equal(s.view().pocket,2);s.press('ok');assert.equal(selected.result.result.itemId,'pokeball');assert.deepEqual(s.state.current(),old);
});
test('FINAL-01 mixed default/cross-pocket duplicate rows keep selected coordinates and default-pocket consumption',()=>{
 const h=mixedPotions(),op=h.G.PSInventory.showBag();h.pocket(3);h.press('down');h.press('ok');h.ready();assert.equal(op.done,false);const c=h.manager._scene._controller;assert.equal(c.selectedTicket.pocket,3);assert.equal(c.selectedTicket.index,1);h.choose('use');h.choose(h.game.party[0].id);h.ready();assert.equal(h.state.current().inventory.pockets[1][0].quantity,2);assert.deepEqual(h.state.current().inventory.pockets[2],[{itemId:'potion',quantity:999},{itemId:'potion',quantity:501}]);const hp=h.state.current().party[0].hp;h.tick();h.tick();assert.equal(h.state.current().party[0].hp,hp);h.press('ok');h.ready();h.press('cancel');h.ready();h.press('cancel');assert.equal(op.result.status,'cancelled');
});
test('FINAL-01 cross-pocket target wait observes ABA and never silently renews original ticket',()=>{
 const h=mixedPotions(),op=h.G.PSInventory.showBag();h.pocket(3);h.press('down');h.press('ok');h.ready();assert.equal(op.done,false,'cross-pocket row must reach menu before the ABA wait');assert.equal(h.view()?.view.kind,'menu');h.choose('use');h.ready();const before=clone(h.state.current()),changed=clone(before);changed.inventory.pockets[2][1].quantity--;h.state.replace(changed);h.app.inventorySnapshot(h.view().token);h.state.replace(before);h.choose(h.game.party[0].id);h.ready();assert.equal(h.view()?.view.kind,'message');assert.deepEqual(h.state.current(),before);h.press('ok');assert.equal(op.result.status,'refused');assert.equal(op.result.reason,'stale-slot');assert.equal(h.app.saveBlocked,false);
});
test('FINAL-01 filtered party row retains original index; direct Toss fallback uses actual row coordinates',async()=>{
 const h=mixedPotions();const g=clone(h.state.current());g.inventory.pockets[2].unshift({itemId:'greatball',quantity:1});h.state.replace(g);h.G.PSManagement.openParty();h.ready();h.press('ok');h.managementChoose('item');h.managementChoose('use');h.ready();h.pocket(3);h.press('down');h.press('ok');h.ready();assert.equal(h.view()?.view.kind,'menu');const c=h.manager._scene._controller.inventoryChild;assert.equal(c.selectedTicket.pocket,3);assert.equal(c.selectedTicket.index,2);h.choose('use');h.ready();assert.equal(h.state.current().inventory.pockets[1][0].quantity,2);h.press('ok');h.ready();h.press('cancel');h.ready();assert.equal(h.G.PSInventory.current(),null);
 // White-box coverage of the defensive no-selectedTicket fallback, not a claimed extra public route.
 const t=mixedPotions();t.G.PSInventory.showBag();t.pocket(3);const ctrl=t.manager._scene._controller;assert.equal(ctrl.selectedTicket,null);ctrl.toss(ctrl.rows()[1]);t.ready();t.press('ok');t.choose('yes');t.ready();assert.equal(t.state.current().inventory.pockets[1][0].quantity,3);t.press('ok');await new Promise(r=>setImmediate(r));t.ready();assert.equal(t.state.current().inventory.pockets[1][0].quantity,2);assert.deepEqual(t.state.current().inventory.pockets[2],[{itemId:'potion',quantity:999},{itemId:'potion',quantity:501}]);t.press('ok');t.ready();t.press('cancel');
});
const displayed=h=>h.drawCalls.filter(d=>d.op==='drawText');
const assertLayout=rows=>{for(const r of rows){assert.ok(r.args[1]>=12);assert.ok(r.args[1]+r.args[3]<=780.01);assert.ok(String(r.args[0]).length*10<=r.args[3]+.01,'text must fit its own region');}for(let i=1;i<rows.length;i++)assert.ok(rows[i-1].args[1]+rows[i-1].args[3]<=rows[i].args[1],'regions must not overlap');};
const assertIconClear=h=>{for(const r of h.drawCalls.filter(d=>d.op==='fillRect'&&d.args[2]===48))for(const d of displayed(h).filter(d=>String(d.args[0]).trim().startsWith('×'))){const a=r.args,b=d.args;assert.ok(!(b[1]<a[0]+a[2]&&b[1]+b[3]>a[0]&&b[2]<a[1]+a[3]&&b[2]+b[4]>a[1]),'item icon must not cover a current-slot quantity region');}};
test('FINAL-02 long bilingual bag names preserve both slot quantities 999/501 independently of total',()=>{
 for(const lang of ['en','zh']){const h=host({edit:(g,c)=>{c.items.potion.name=(lang==='zh'?'超长道具名称':'Long potion name ').repeat(30);c.items.potion.nameKey='test.final.long';g.inventory=E.inventory.inventoryFromBag({potion:1500},c.items);}});h.G.language=lang;h.G.PSInventory.showBag();h.pocket(2);assert.ok(h.view().text.some(s=>s.includes('999')),'first slot must retain 999');assert.ok(h.view().text.some(s=>s.includes('501')),'second slot must retain 501');assert.ok(h.view().text.some(s=>s.includes('1500')));for(const y of [72,101])assertLayout(displayed(h).filter(d=>d.args[2]===y).sort((a,b)=>a.args[1]-b.args[1]));assertIconClear(h);h.press('cancel');}
});
test('FINAL-02 long bilingual shop names preserve distinct unit price 200 and owned 20 regions',()=>{
 for(const lang of ['en','zh']){const h=host({edit:(g,c)=>{c.items.pokeball.name=(lang==='zh'?'超长精灵球名称':'Long ball name ').repeat(30);c.items.pokeball.nameKey='test.final.ball';}});h.G.language=lang;const op=h.G.PSInventory.openShop({stock:['pokeball']});h.choose('buy');h.ready();assert.ok(h.view().text.some(s=>s.includes(lang==='zh'?'价格：200':'Price: 200')));assert.ok(h.view().text.some(s=>s.includes(lang==='zh'?'持有总量：20':'Owned: 20')));assertLayout(displayed(h).filter(d=>d.args[2]===56).sort((a,b)=>a.args[1]-b.args[1]));h.press('cancel');h.choose('close');assert.equal(op.result.status,'cancelled');}
});
test('FINAL-02 safe-integer prices/owned values, forbidden-row reasons and long trade totals remain visible',()=>{
 for(const lang of ['en','zh']){const h=host({edit:(g,c)=>{for(const id of ['pokeball','box-link']){c.items[id].name='Long 长名称 '.repeat(60);c.items[id].nameKey='test.final.'+id;}c.items.pokeball.price=Number.MAX_SAFE_INTEGER;g.inventory=E.inventory.addItems(g.inventory,'box-link',1,c.items,E.inventory.inventoryPolicy(c));g.inventory.pockets[2][0].quantity=Number.MAX_SAFE_INTEGER;g.money=Number.MAX_SAFE_INTEGER;}});assert.deepEqual(E.saveSchema.validateGame(h.state.current()),[]);h.G.language=lang;const op=h.G.PSInventory.openShop({stock:['pokeball'],allowSell:true});h.choose('buy');h.ready();assert.ok(h.view().text.some(s=>s.includes((lang==='zh'?'价格：':'Price: ')+Number.MAX_SAFE_INTEGER)));assert.ok(h.view().text.some(s=>s.includes((lang==='zh'?'持有总量：':'Owned: ')+Number.MAX_SAFE_INTEGER)));assertLayout(displayed(h).filter(d=>d.args[2]===56).sort((a,b)=>a.args[1]-b.args[1]));h.press('cancel');h.choose('sell');h.ready();const forbiddenRow=h.view().view.items.findIndex(r=>r.key==='box-link');assert.ok(forbiddenRow>=0);const reasonDraws=displayed(h).filter(d=>d.args[2]===56+forbiddenRow*31).sort((a,b)=>a.args[1]-b.args[1]);assert.ok(reasonDraws.some(d=>String(d.args[0]).includes(lang==='zh'?'不能出售':'cannot be sold')),'long forbidden row must retain its own reason');assertLayout(reasonDraws);h.press('cancel');h.choose('close');assert.equal(op.done,true);
 const small=host({edit:(g,c)=>{c.items.pokeball.name='Long 长名称 '.repeat(60);c.items.pokeball.nameKey='test.final.confirm';}});small.G.language=lang;small.G.PSInventory.openShop({stock:['pokeball']});small.choose('buy');small.choose('pokeball');small.ready();small.press('right');small.press('ok');small.ready();assert.ok(small.view().text.some(s=>s.includes(lang==='zh'?'合计：2200':'Total: 2200')),'confirmation must preserve actual total outside long name');const before=clone(small.state.current());small.choose('no');assert.deepEqual(small.state.current(),before);}
});
